export async function ensureReviewedAthleteImport(){
 const database=db();
 const done:any=await database.prepare('SELECT id FROM audit WHERE id=?').bind(IMPORT_SENTINEL).first();
 if(done)return;
 const completed="INSERT OR IGNORE INTO audit(id,actor,action,entity_id,created_at) VALUES ('"+IMPORT_SENTINEL+"','felipe','athlete_import_batch','"+IMPORT_SENTINEL+"',strftime('%Y-%m-%dT%H:%M:%fZ','now'))";
 await database.batch([...IMPORT_STATEMENTS,completed].map(sql=>database.prepare(sql)));
}
